package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Replacement for System.Buffers.ArrayBufferWriter&lt;T&gt; (generated by CSharpToJava converter).
 *
 * <p><b>Geometric growth.</b> The backing array grows by
 * {@code length + max(sizeHint, length)} exactly like .NET's
 * {@code ArrayBufferWriter<T>} (doubling once the buffer is at least as large as the
 * hint). The previous fixed {@code +4096} step made writing N elements copy
 * O(N^2 / step) elements: emitting 8 MB of JSON copied ~61 GB and took ~10 s by
 * itself.
 *
 * <p><b>Full window.</b> {@link #getMemory(int)} hands back a view over the FULL
 * remaining capacity ({@code buffer.AsMemory(index)} in .NET); "at least sizeHint"
 * is a lower bound, not a cap. The generated {@code Utf8JsonWriter} relies on the
 * exact window size for its Committed/BytesPending bookkeeping —
 * Utf8JsonWriterTests.writeJsonWritesToIBWOnDemand_Dispose pins byte counts that
 * only the full-window contract reproduces. Writes through the returned view are
 * O(1) regardless of its size (no per-write materialization), so the larger
 * window costs nothing.
 */
public class ArrayBufferWriter<T> implements IBufferWriter<T> {

    private T[] buffer;
    private int written;

    private static final int MIN_BUFFER_SIZE = 256;

    /** Mirrors ArrayBufferWriter&lt;T&gt;(int initialCapacity). */
    @SuppressWarnings("unchecked")
    public ArrayBufferWriter(int initialCapacity) {
        this.buffer = (T[]) new Object[Math.max(initialCapacity, MIN_BUFFER_SIZE)];
        this.written = 0;
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;(). */
    public ArrayBufferWriter() {
        this(MIN_BUFFER_SIZE);
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.WrittenMemory. */
    public ReadOnlyMemory<T> getWrittenMemory() {
        @SuppressWarnings("unchecked")
        T[] copy = (T[]) Arrays.copyOfRange(buffer, 0, written);
        return new ReadOnlyMemory<>(copy);
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.WrittenSpan — ReadOnlySpan, matching C# semantics. */
    public ReadOnlySpan<T> getWrittenSpan() {
        @SuppressWarnings("unchecked")
        T[] copy = (T[]) Arrays.copyOfRange(buffer, 0, written);
        return new ReadOnlySpan<>(copy);
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.WrittenCount. */
    public int getWrittenCount() {
        return written;
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.Capacity. */
    public int getCapacity() {
        return buffer.length;
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.GetMemory(int sizeHint). */
    @Override
    public ReadOnlyMemory<T> getMemory(int sizeHint) {
        int hint = Math.max(sizeHint, 1);
        EnsureCapacity(hint);
        // Return a view starting at the written offset over the FULL remaining
        // capacity, matching .NET's buffer.AsMemory(index): the IBufferWriter
        // contract's "at least sizeHint" is a lower bound, not a cap.
        return new ReadOnlyMemory<>(buffer, written, buffer.length - written);
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.Advance(int count). */
    @Override
    public void advance(int count) {
        if (count < 0 || written + count > buffer.length) {
            throw new IndexOutOfBoundsException("count=" + count + ", written=" + written + ", capacity=" + buffer.length);
        }
        written += count;
    }

    /** Mirrors ArrayBufferWriter&lt;T&gt;.Clear(). */
    public void clear() {
        written = 0;
    }

    /**
     * Mirrors {@code ArrayBufferWriter<T>.CheckAndResizeBuffer}: growth is
     * {@code length + max(sizeHint, length)}, i.e. it doubles once the buffer is at least
     * as large as the requested hint and otherwise grows by the hint. Generated tests pin
     * this exact behaviour (the first growth of a default writer must be exactly +4096),
     * so it must not be replaced by plain doubling.
     *
     * <p>Because the hint never depends on the total output size, reallocation copying is
     * amortized O(N) instead of the previous {@code +4096} fixed step, which copied
     * O(N^2 / 4096) elements.
     */
    @SuppressWarnings("unchecked")
    private void EnsureCapacity(int sizeHint) {
        if (sizeHint <= buffer.length - written) {
            return;
        }
        int growBy = Math.max(sizeHint, buffer.length);
        long newSize = (long) buffer.length + growBy;
        if (newSize > Integer.MAX_VALUE - 8) {
            newSize = Integer.MAX_VALUE - 8;
        }
        buffer = (T[]) Arrays.copyOf(buffer, (int) newSize);
        if (buffer.length - written < sizeHint) {
            throw new OutOfMemoryError("ArrayBufferWriter cannot grow beyond " + buffer.length + " elements");
        }
    }
}
